<script lang="ts">
 import {onMount} from 'svelte';import {Api} from '$lib/api';
 let messages=$state<any[]>([]);let regions=$state<any[]>([]);let error=$state('');
 async function load(){try{[messages,regions]=await Promise.all([Api.loraMessages(),Api.loraRegions()]);error=''}catch(e){error=String(e)}}onMount(load);
</script>
<div class="page"><h1>LoRa</h1><p class="muted">LoRa packet activity and supported regional plans.</p>{#if error}<p class="error">{error}</p>{/if}<section class="card"><div class="title"><h2>Regions</h2><button onclick={load}>Refresh</button></div><div class="chips">{#each regions as r}<span>{typeof r==='object'?JSON.stringify(r):r}</span>{:else}<i>No regions reported</i>{/each}</div></section><section class="card"><h2>Messages</h2>{#each messages as m}<div class="row">{#each Object.entries(m) as [k,v]}<span><small>{k}</small>{typeof v==='object'?JSON.stringify(v):String(v??'—')}</span>{/each}</div>{:else}<div class="empty">No LoRa messages</div>{/each}</section></div>
<style>.page{padding:16px;overflow-y:auto;height:100%}.muted,small,.empty,i{color:var(--fg-dim)}.error{color:var(--danger)}.card{margin:12px 0;padding:14px;background:var(--bg-elev);border:1px solid var(--line);border-radius:8px}.title{display:flex;justify-content:space-between}.title h2,h2{margin:0 0 8px;font-size:14px}button,.chips span{background:var(--bg);color:var(--fg);border:1px solid var(--line);padding:6px 9px;border-radius:5px}.chips{display:flex;gap:7px;flex-wrap:wrap;font:12px var(--mono)}.row{display:flex;gap:16px;border-top:1px solid var(--line);padding:8px 0;font:12px var(--mono);flex-wrap:wrap}.row span{min-width:120px}.row small{display:block;font:10px var(--sans)}.empty{text-align:center;padding:20px}</style>
